      interviewQuestions: [
        FireSafetyQuestion('What is the purpose of a fire risk assessment?', 'To identify fire hazards and people at risk, evaluate existing controls, determine further measures and verify that residual risk is acceptable.'),
        FireSafetyQuestion('When should it be reviewed?', 'When there is a material change in layout, occupancy, fuel, process, protection system, incident, drill finding or applicable requirements, and at the required planned interval.'),
        FireSafetyQuestion('What is residual risk?', 'The risk remaining after specified controls are implemented and verified.'),
        FireSafetyQuestion('Can an HSE Officer approve fire engineering design values?', 'Only if formally competent and authorized. Design/code compliance values should be confirmed by the qualified designer and relevant authority.'),
        FireSafetyQuestion('How do you close a fire-risk action?', 'Verify the control in the field, review objective evidence, confirm the responsible person and date, and update the action register; do not close based only on verbal assurance.'),
      ],
      references: [
        'Current UAE Fire and Life Safety Code of Practice and applicable local Civil Defence authority requirements.',
        'Approved project fire strategy, drawings, risk matrix and emergency plan.',
        'UAE regulatory and authority circulars applicable to the project; confirm current version with the authority.',
        'ISO 31000 risk management principles — supplementary framework, not a fire-code substitute.',
      ],
    ),
    FireSafetyTopic(
      id: 'FLS-05',
      title: 'Fire Extinguishers',
      subtitle: 'Types, selection, safe use, inspection and maintenance',
      icon: Icons.fire_extinguisher_rounded,
      accent: Color(0xFF249B82),
      overview: 'Portable fire extinguishers are first-response equipment for small incipient fires. Selection must match the fuel, electrical condition, environment, user competency and authority-approved fire strategy. They are not a substitute for alarm, evacuation, fixed protection or emergency services.',
      sections: [
        FireSafetySection('Common extinguisher agents', [
          'Water: primarily cooling for suitable Class A materials; not for energized electrical equipment, burning liquids or water-reactive materials.',
          'Foam: suitable for specified Class A/B risks according to label; avoid use where incompatible with energized equipment or chemicals.',
          'Carbon dioxide (CO₂): useful for certain flammable-liquid/electrical risks; discharge horn can become very cold and ventilation/re-ignition concerns remain.',
          'Dry chemical powder: agent type and rating determine suitability; discharge reduces visibility and can affect sensitive equipment.',
          'Wet chemical: designed for specified cooking-oil/fat hazards; follow label and appliance procedure.',
          'Class D powder: must be selected for the specific combustible metal; ordinary agents may be ineffective or dangerous.',
        ]),
        FireSafetySection('Selection & positioning', [
          'Base type, rating, quantity and location on approved design, hazard assessment, authority requirements and applicable code.',
          'Consider travel/access, visibility, mounting, environmental exposure, tampering, obstruction and user capability.',
          'Do not invent universal spacing or mounting-height values; verify the adopted code, approved drawings and manufacturer instructions.',
          'Provide signage and identification consistent with the approved site plan and applicable requirements.',
        ]),
        FireSafetySection('Safe operating method', [
          'Raise alarm and ensure emergency services/site response are notified.',
          'Select the correct labelled extinguisher; maintain a clear escape route behind you and stay upwind where relevant.',
          'Use only if trained and the fire is small, contained and not producing dangerous smoke/heat.',
          'Follow the device instructions (often remembered as PASS: Pull, Aim, Squeeze, Sweep, where applicable to the model).',
          'Withdraw if fire grows, agent is ineffective, smoke increases or escape is threatened. Do not turn your back on the fire while retreating.',
          'After use, report and remove the unit from service for authorized recharge/replacement, even if only partly discharged.',
        ]),
        FireSafetySection('Inspection & maintenance', [
          'Check correct type/rating, location, accessibility, signage, label legibility, body/corrosion, pin/seal, hose/nozzle, pressure indicator where fitted and service status.',
          'Inspection frequency and maintenance must follow current authority-adopted code, approved project schedule, manufacturer and competent service provider; record the actual governing basis.',
          'Do not dismantle, pressure-test or recharge unless authorized and competent.',
          'Defective, discharged, expired or inaccessible units must be made unavailable for reliance, replaced or otherwise covered by approved temporary controls.',
        ]),
        FireSafetySection('Responsibilities & records', [
          'Employer/project management provides suitable equipment and maintenance resources.',
          'HSE/supervisor verifies availability and records findings; competent service provider performs required servicing.',
          'Workers receive awareness/training and use equipment only within training and safe conditions.',
          'Maintain asset ID, location, agent/rating, inspection date, defects, action owner, service evidence and next due date.',
        ]),
        FireSafetySection('Stop-work & emergency response', [
          'Stop/restrict affected activity if required extinguisher is missing, wrong type, damaged, discharged, overdue under governing schedule or blocked.',
          'Do not attempt firefighting on pressurized cylinders, unknown chemicals, reactive metals or a fire beyond incipient stage unless specialist response is assigned.',
          'Evacuate, account for people and provide responders with fuel/SDS information.',
        ]),
        FireSafetySection('Extinguisher parts and pre-use checks', [
          '''Common components include cylinder/body, operating handle/lever, safety pin and tamper seal, label, hose or horn/nozzle, discharge mechanism and pressure indicator where fitted. Design varies by agent and manufacturer.''',
          '''Confirm the label is readable and identifies the agent, fire rating, operating instructions, limitations and service information. Do not identify an extinguisher only by colour; labels and approved local identification govern.''',
          '''Check the unit is in its designated location, visible, accessible, correctly mounted/secured, and not blocked by materials or locked behind an obstruction. Check signage and any environmental damage.''',
          '''Look for corrosion, dents, leakage, damaged hose/nozzle, missing pin/seal, abnormal pressure indication where fitted, broken bracket, expired/overdue service status under the governing schedule, or evidence of discharge/tampering.''',
          '''A gauge in the green zone alone does not prove the unit is serviceable. Check the full condition and record asset ID, date, location, findings and action.''',
        ]),
        FireSafetySection('Safe use — PASS and decision limits', [
          '''P — Pull the pin or release the safety device as shown on the actual model. A different mechanism may apply; follow training and manufacturer label.''',
          '''A — Aim at the base/source of the fire from a safe position, not at the flames alone. Do not approach through smoke or heat.''',
          '''S — Squeeze the operating lever while maintaining stable footing and a clear route behind you.''',
          '''S — Sweep across the burning area as trained. Use short controlled bursts only if the model instructions and training permit; watch for re-ignition and withdraw early.''',
          '''PASS is a memory aid, not permission to fight every fire. Alarm/evacuation take priority. Do not fight if fire is spreading, smoke is increasing, fuel is unknown, cylinders/reactive metals are involved, the correct agent is absent or escape is threatened.''',
          '''CO₂ can create an asphyxiation risk in small or poorly ventilated spaces; powder can obscure vision and irritate breathing. Consider bystanders, wind, electrical state and re-ignition before any use.''',
        ]),
        FireSafetySection('Inspection, maintenance and records', [
          '''Separate routine visual inspection from competent maintenance, servicing and pressure testing. Only an authorized competent provider should perform work requiring disassembly, recharge or pressure testing.''',
          '''Inspection frequency is governed by the applicable UAE authority-adopted code, approved project schedule, manufacturer and competent service provider. A Dubai Civil Defence annexure recommends monthly visual checks and log entries; confirm applicability to the specific premises and current approved requirements before using it as the project rule.''',
          '''When a unit is removed for service, provide approved equivalent interim protection or restrict affected work/area as determined by the responsible authority and risk assessment.''',
          '''Maintain register fields: asset ID, type/agent, rating, location, inspection date, condition, defect, temporary control, action owner, target date, service certificate and verified closure.''',
        ]),
        FireSafetySection('Placement and technical values — verification rule', [
          '''Do not apply one universal extinguisher travel distance, mounting height, quantity or service interval to every UAE site. These depend on hazard class, occupancy, adopted code edition, approved drawings, authority conditions and project fire strategy.''',
          '''OSHA distances and annual/monthly rules are United States workplace requirements, not automatically UAE legal requirements. They may be shown as comparative learning only and must be clearly labeled as US-specific supplementary material.''',
          '''For design or compliance decisions, check the current UAE Fire & Life Safety Code, relevant Emirate Civil Defence approval, approved fire strategy, manufacturer instructions and competent fire-safety professional advice.''',
        ]),
        FireSafetySection('Site example', [
          'A workshop extinguisher has a broken seal and unreadable label. Tag it out, arrange an approved replacement immediately, assess whether temporary controls or work restriction are needed, record the defect and verify closure.',
        ]),
      ],
      checklist: [
        'Extinguisher type and rating match the approved fire risk assessment and location.',
        'Unit is in its designated location, visible and accessible.',
        'Signage and operating label are legible.',
        'Pin and tamper seal are present and undamaged.',
        'Hose, horn/nozzle, handle and body have no visible damage or corrosion.',
        'Pressure indicator is within the manufacturer-marked range where fitted.',
        'Inspection/service tag and records meet the applicable approved schedule.',
        'Unit is not discharged, obstructed, leaking or otherwise defective.',
        'Defects are tagged, reported, replaced/controlled and closed with evidence.',
        'Relevant workers know alarm/evacuation priority and extinguisher-use limitations.',
      ],
      requiredDocuments: [
        'Approved fire extinguisher layout / location plan',
        'Fire extinguisher asset register (ID, type, rating, location)',
        'Routine inspection checklist and defect/corrective-action log',
        'Competent service / maintenance certificates and work orders',
        'Fire risk assessment and emergency response plan',
        'User training / fire awareness records',
      ],
      interviewQuestions: [
        FireSafetyQuestion('What does PASS commonly stand for?', 'Pull the pin, Aim at the base of the fire, Squeeze the handle and Sweep side to side; follow the actual extinguisher instructions and training.'),
        FireSafetyQuestion('Can CO₂ be used in a small enclosed room?', 'Only within the equipment label, training and risk controls; CO₂ can displace oxygen and create an asphyxiation hazard, so evacuation and ventilation considerations are essential.'),
        FireSafetyQuestion('What do you do with a defective extinguisher?', 'Tag/remove it from reliance, provide approved replacement or interim controls, report it, arrange competent service and document verified closure.'),
        FireSafetyQuestion('Who may service an extinguisher?', 'A competent, authorized service provider under applicable authority, manufacturer and project requirements.'),
        FireSafetyQuestion('When should a worker attempt to extinguish a fire?', 'Only when trained, alarm is raised, correct agent is available, fire is small and incipient, conditions are safe and a clear escape route remains; otherwise evacuate.'),
      ],
      references: [
        'Current UAE Fire and Life Safety Code of Practice and applicable Civil Defence authority requirements.',
        'Approved project fire strategy, extinguisher schedule and site emergency plan.',
        'Extinguisher manufacturer label, operating and maintenance instructions.',
        'OSHA portable extinguisher basics — United States guidance, not UAE law: https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers/about',
        'OSHA US workplace selection/inspection/training rules (29 CFR 1910.157) — comparative only: https://www.osha.gov/etools/evacuation-plans-procedures/emergency-standards/portable-extinguishers/required',
        'NFPA 10 — supplementary reference; verify whether and which edition is adopted by the applicable authority/project.',
      ],
    ),

    FireSafetyTopic(
      id: 'FLS-06',
      title: 'Fire Detection & Alarm Systems',
      subtitle: 'Detection, manual alarm, notification, monitoring and impairment control',
      icon: Icons.notifications_active_rounded,
      accent: Color(0xFFCC3D3D),
      overview: 'Fire detection and alarm systems identify a developing fire, notify occupants and initiate approved cause-and-effect actions. System design, zoning, device selection, interfaces, testing and acceptance must follow the current authority-approved fire strategy, approved drawings, manufacturer requirements and competent specialist procedures. HSE staff should understand operational checks and escalation, but must not alter or disable system programming.',
      sections: [
        FireSafetySection('Purpose, components & terminology', [
          'A typical system may include a fire alarm control panel, automatic detectors, manual call points, audible/visual notification devices, interfaces, power supplies, batteries, communication links and remote monitoring.',
          'Smoke detectors respond to smoke particles; heat detectors respond to temperature or rate-of-rise criteria; flame detectors are selected for specific risks and line-of-sight conditions. Device choice is a design decision, not a field substitution.',
          'A manual call point allows a person to initiate an alarm. Alarm notification may use sounders, beacons, voice messages or approved combinations depending on occupancy and ambient conditions.',
          'A zone identifies an area for alarm indication and response. An addressable system may identify individual devices; exact system behaviour depends on the approved design.',
          'Alarm, fault, supervisory and disablement indications are different conditions. Treat any unexpected fault or disabled life-safety function as an impairment requiring prompt escalation.',
        ]),
        FireSafetySection('Operational checks & alarm response', [
          'Workers must know the alarm signal, site emergency number, evacuation route, assembly point and who receives alarm reports.',
          'On hearing an alarm, stop work safely, warn nearby persons and evacuate by the designated route. Do not wait for a supervisor to confirm an alarm unless the approved plan specifically provides controlled staged instructions.',
          'At the panel, only trained and authorized personnel should interpret indications, acknowledge/reset or operate controls. Never silence or reset to clear an alarm without following incident control and site procedure.',
          'Do not cover detectors, obstruct call points, paint devices, hang items from cables or alter settings. Report dust, water ingress, impact damage, nuisance alarms and repeated faults.',
          'A detector activation must be investigated by the authorized response team under the emergency plan. Do not assume it is a false alarm.',
        ]),
        FireSafetySection('Inspection, testing & impairment management', [
          'Routine visual checks look for physical damage, obstruction, contamination, missing covers, accessible manual call points, visible panel faults and clear access to equipment.',
          'Functional testing, sensitivity testing, programming, loop isolation and interface testing must be performed by competent authorized fire-alarm personnel under approved method statements and permits.',
          'Before planned isolation, obtain authorization, define affected zones/devices, duration, risk, notification, compensatory measures, monitoring and restoration owner.',
          'Where detection/alarm is impaired, notify responsible management and relevant parties, restrict or suspend affected activities as required, provide approved temporary measures such as fire watch, and record start/end times.',
          'After work, verify restoration and required functional checks; close impairment only with documented confirmation from the authorized competent person.',
        ]),
        FireSafetySection('HSE and supervisor responsibilities', [
          'Verify workers know how to raise the alarm and evacuate; keep call points, panels and sounders unobstructed.',
          'Check that alarm impairment is not concealed by temporary works, maintenance or construction activity.',
          'Coordinate hot work, dusty work, ceiling works and shutdowns with the fire-system owner to avoid unauthorized isolation or contamination.',
          'Keep alarm event records, inspection/test reports, defect logs, impairment permits, approvals, notifications and restoration evidence.',
        ]),
        FireSafetySection('Stop-work & site example', [
          'Stop or restrict affected work when a critical alarm zone is disabled without authorization, alarm audibility is inadequate, a call point is inaccessible or a fault leaves people without the approved warning arrangement.',
          'Example: ceiling contractors plan dusty drilling near smoke detectors. Coordinate with the authorized fire-system owner; use approved protection/isolation controls only when authorized, apply compensatory measures, control dust, then ensure detectors are uncovered, inspected and restored before handover.',
        ]),
        FireSafetySection('Detailed field workflow, testing and failure scenarios', [
          'Before occupancy or handover, the competent fire-alarm specialist verifies approved device locations, loop/zone mapping, cause-and-effect actions, interfaces, audibility/visibility design, standby power and monitoring against approved drawings and acceptance criteria.',
          'For a reported alarm: announce the location and indication to the incident controller, initiate the site emergency plan, protect evacuation, and allow the authorized response team to investigate. Do not assume a detector activation is false merely because no flame is visible.',
          'For a fault: record panel text/device/zone, time, affected function and reported symptoms; notify the designated system owner immediately. Apply the approved impairment process, including risk review, notifications, temporary warning/fire watch or activity restriction where required.',
          'For planned detector protection during dusty work, obtain written authorization, identify exact devices and time window, control dust at source, provide compensatory measures, and maintain a named person responsible for restoration. Do not use bags, tape or covers unless the approved procedure specifically permits them.',
          'After maintenance, the authorized technician removes temporary protection, restores all isolations, confirms normal panel status, tests affected devices/interfaces as required, informs stakeholders and signs the restoration record. HSE verifies evidence; HSE does not reprogram the panel.',
          'Common failure modes include detector obstruction, wrong device type for environment, water ingress, damaged cabling, battery degradation, disabled interfaces, poor alarm audibility and uncommunicated isolation. Each requires documented defect control and closure verification.',
        ]),
      ],
      checklist: [
        'Fire alarm panel shows normal status or all faults are formally assessed and controlled.',
        'Manual call points, detectors and notification devices are visible and unobstructed.',
        'No unauthorized covering, painting, damage or isolation is present.',
        'Workers know the alarm signal, emergency number, escape route and assembly point.',
        'Planned impairment has authorization, risk assessment, notifications and compensatory controls.',
        'Testing and maintenance are performed by competent authorized personnel.',
        'Alarm event, defect and restoration records are retained.',
      ],
      requiredDocuments: [
        'Approved fire alarm drawings, cause-and-effect matrix and system design documents',
        'Fire alarm inspection, testing and maintenance reports',
        'Alarm event / fault log and corrective-action register',
        'Fire system impairment permit, risk assessment and notification record',
        'Competency/authorization records for system technicians',
        'Emergency Response Plan and worker alarm-awareness records',
      ],
      interviewQuestions: [
        FireSafetyQuestion('What is the difference between an alarm and a fault?', 'An alarm indicates a fire/emergency signal requiring response; a fault indicates a system problem that may compromise reliability. Both must be handled under the approved procedure.'),
        FireSafetyQuestion('Who may isolate a detector or alarm zone?', 'Only an authorized competent person under the approved impairment procedure, with risk assessment, notification, compensatory controls and documented restoration.'),
        FireSafetyQuestion('What should workers do when the fire alarm sounds?', 'Stop work safely, warn others and evacuate by the designated safe route; do not delay to collect belongings or investigate.'),
        FireSafetyQuestion('Why should an alarm not be reset immediately?', 'Resetting may erase or obscure event information and could leave an actual fire uninvestigated; the authorized incident team must follow the response procedure.'),
        FireSafetyQuestion('What records demonstrate alarm system control?', 'Approved drawings/cause-and-effect, test and maintenance reports, event/fault logs, impairment authorization, corrective actions and restoration evidence.'),
      ],
      references: [
        'UAE Fire and Life Safety Code of Practice — current authority-approved edition and applicable Emirate amendments.',
        'Dubai Civil Defence official code/FAQ portal: https://www.dcd.gov.ae/portal/en/preventive-safety/rules-regulations/faq-uae-fire-and-life-safety-code-of-practice',
        'UAE Government fire safety information: https://u.ae/en/information-and-services/justice-safety-and-the-law/fire-safety',
        'Approved fire strategy, fire alarm cause-and-effect, manufacturer instructions and competent service-provider procedures.',
        'NFPA 72 — supplementary only unless adopted by authority or contract; verify edition and applicability.',
      ],
    ),
    FireSafetyTopic(
      id: 'FLS-07',
      title: 'Emergency Evacuation & Means of Escape',
      subtitle: 'Safe alarm response, escape routes, assembly, accountability and re-entry control',
      icon: Icons.exit_to_app_rounded,
      accent: Color(0xFF2879C7),
      overview: 'Evacuation is the organized movement of people from a threatened area to a designated place of safety. Means of escape includes the route, doors, corridors, stairs, final exits and external discharge areas. The approved evacuation strategy, building design, occupancy, authority conditions and site emergency plan govern route capacity, travel distances and arrangements.',
      sections: [
        FireSafetySection('Evacuation principles & route elements', [
          'Recognize alarm and follow the approved site/building evacuation instruction. Do not wait for visual confirmation of fire.',
          'A route normally includes access to an exit, protected or designated passage, stair or exit passageway and final discharge to a safe external area or approved refuge arrangement.',
          'Keep corridors, stairways, landings, final exits and external discharge areas free of stored material, waste, tools, vehicles and temporary cables.',
          'Exit doors must remain usable in the required direction and manner under the approved design. Do not lock, chain, wedge or obstruct an exit contrary to approved requirements.',
          'Use stairs during fire evacuation unless the approved emergency strategy specifically identifies an evacuation lift and trained procedure. Do not use ordinary lifts.',
        ]),
        FireSafetySection('Evacuation sequence for workers', [
          'Stop work safely if this can be done immediately without delay or exposure; leave tools and belongings.',
          'Warn nearby people, activate the alarm if needed and move promptly using the nearest safe designated route. Avoid smoke and never enter a smoke-filled corridor.',
          'Assist visitors or persons requiring help only within the assigned plan and without creating additional victims. Use designated assistance/refuge procedures where provided.',
          'Proceed to the assigned assembly point, remain available for headcount and report missing persons, last known location and hazards to the incident controller.',
          'Do not leave the assembly point, re-enter the building or restart work until the authorized authority/site incident controller declares it safe.',
        ]),
        FireSafetySection('People requiring assistance & accountability', [
          'Plan for contractors, visitors, night shifts, lone workers, mobility/sensory needs, language differences and people unfamiliar with the premises.',
          'Assign trained helpers or buddies where the approved plan requires; identify safe refuge/communication arrangements and avoid improvising lifts or carrying methods.',
          'Maintain current attendance/visitor records and a clear process for reporting missing persons. Do not send untrained workers back inside to search.',
          'Assembly points must be away from emergency access, smoke, hazardous storage, traffic and secondary hazards; use alternate points if the primary point is unsafe.',
        ]),
        FireSafetySection('Drills, route changes & stop-work', [
          'Conduct drills at the interval required by authority, project and occupancy arrangements; include realistic shifts and relevant contractors without creating unsafe simulations.',
          'Record alarm recognition, route obstruction, evacuation flow, headcount, assistance, communication, timing, observations and corrective actions.',
          'Reassess when construction changes access, hoardings, temporary stairs, occupancy, work fronts or assembly-point safety.',
          'Stop affected work if a required exit is locked/blocked, route is exposed to smoke/fire, emergency access is obstructed or a safe evacuation arrangement is not available.',
        ]),
        FireSafetySection('Site example', [
          'A construction hoarding blocks the usual corridor to a stair. Do not simply redirect workers verbally and continue. The responsible competent team must approve and communicate a safe alternate route, update drawings/signage and brief all shifts before work resumes.',
        ]),
        FireSafetySection('Detailed evacuation planning and field execution', [
          'The evacuation plan must identify alarm meanings, primary and alternative routes, final exits, assembly points, emergency contacts, roles, visitor/contractor accountability, assistance arrangements and re-entry authority. Brief the plan in languages and formats workers understand.',
          'Before each shift, check that routes and exits are open, illuminated as designed, signed, free of stored materials and not compromised by scaffolds, temporary cables, deliveries or vehicle parking. Report any changed route and update signs/briefings before work proceeds.',
          'On alarm: stop equipment only when safe and without delaying escape; leave tools and belongings; use the nearest safe designated route; assist others only within training and without entering smoke; proceed to the assigned assembly point and remain available for headcount.',
          'Wardens or supervisors report headcount status, missing persons, last known location, injuries, blocked routes and hazards to the incident controller. Never dispatch untrained workers back inside to search; give information to emergency responders.',
          'For persons needing assistance, establish a confidential individual plan, assigned helpers/deputies, communication method and approved refuge/evacuation arrangement. Do not improvise an evacuation lift or carry method outside the approved plan and training.',
          'Re-entry is prohibited until the incident controller or competent authority gives formal clearance. After drills or real events, record route delays, congestion, alarm audibility, assistance issues and corrective actions with owners and effectiveness checks.',
        ]),
      ],
      checklist: [
        'Evacuation alarm and instructions are known to workers and visitors.',
        'Approved escape routes, stairs and final exits are clear and usable.',
        'Exit doors and hardware are not locked or obstructed contrary to approved design.',
        'Assembly point and alternate point are identified and accessible.',
        'Visitors, contractors and persons needing assistance are covered by the plan.',
        'Attendance/headcount and missing-person reporting process is available.',
        'Emergency vehicle access and responder routes remain clear.',
        'Drill findings and route changes are documented and communicated.',
      ],
      requiredDocuments: [
        'Approved evacuation plan and escape-route drawings',
        'Emergency Response Plan, contact list and assembly-point map',
        'Occupancy/visitor/contractor attendance and headcount procedure',
        'Personal assistance or designated evacuation support arrangements where required',
        'Fire drill records, observations and corrective-action closure',
        'Temporary route-change risk assessment, approval and communication record',
      ],
      interviewQuestions: [
        FireSafetyQuestion('What is the first priority when a fire alarm sounds?', 'Protect life: stop safely, warn others and evacuate by the designated safe route without delay.'),
        FireSafetyQuestion('Why should ordinary lifts not be used?', 'They may lose power, open onto a fire-affected floor or expose occupants to smoke; follow the approved evacuation strategy and use stairs unless a specifically approved evacuation lift procedure applies.'),
        FireSafetyQuestion('What should a supervisor do at the assembly point?', 'Account for the team using reliable attendance information, report missing persons and last known locations, keep people clear of responders and await incident-controller instructions.'),
        FireSafetyQuestion('Can a worker re-enter to collect equipment?', 'No. Re-entry is prohibited until authorized incident control or the competent authority declares it safe.'),
        FireSafetyQuestion('What if an exit route is blocked?', 'Stop/restrict affected activity, notify responsible management, use only an approved safe alternative after communication and verification, and record the corrective action.'),
